WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_ms_ana_comic'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '漫画类', 'kp-ms-ana-comic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合分析：漫画类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "看图说话，翻译成文字后再进行综合分析。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、读图四要素"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看标题：漫画如果有标题，直接就是主题！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看文字：漫画里人物身上的标签、对话框里的文字，是破题的最关键线索。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看夸张部位：如果一个人肚子画得极大，脑袋画得极小，说明在讽刺“脑满肠肥但不干实事”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看对比：前后两幅图的变化，或者图里两个不同人物的区别。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题结构"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "第一段必须是：“考官您好，这幅漫画向我们展示了这样一个画面……（用生动的语言把漫画描述一遍）。它深刻地讽刺/赞扬了现实社会中的……现象。” 然后剩下的全部转入“社会现象类”的答题套路。"}]}]}$$ AS jsonb), NULL, '漫画类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "综合分析", "漫画题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_ana_comic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
